<script setup lang="ts">
import { computed, inject, onBeforeUnmount, ref, watch, type ComputedRef } from 'vue';
import { ArrowRight, CheckCheck, ClipboardList, GitBranch, LoaderCircle, Plus, RefreshCw, Users, X } from 'lucide-vue-next';
import type { AnnotationTaskView, WorkflowSummary } from '../../../../packages/shared/src/workflow-types';
import type { BranchItem, RepositoryPermissions, RepositorySettingsState } from '@oxen/shared';
import { post, request, patch } from '../api';
import { useAppStore } from '../stores/app';
const props=defineProps<{base:string;branch:string}>();
const emit=defineEmits<{open:[taskId:string,branch:string,rowId?:string];changed:[]}>();
const app=useAppStore(),permissions=inject<ComputedRef<RepositoryPermissions>>('repositoryPermissions');
const canManage=computed(()=>permissions?.value.capabilities?.['tasks.manage']??permissions?.value.admin??false);
const data=ref<WorkflowSummary>(),settings=ref<RepositorySettingsState>(),loading=ref(false),busy=ref(false),error=ref(''),showCreate=ref(false),activeId=ref(''),filter=ref('all');
const selected=ref<string[]>([]),samplePage=ref(1),reviewComment=ref(''),replacement=ref('');
const form=ref({title:'',assigneeIds:[] as string[],reviewerId:'owner',mode:'review' as 'review'|'independent',branchPrefix:'annotate/task',note:''});
const people=computed(()=>[{id:'owner',name:'实例管理员',role:'owner',capabilities:undefined as string[]|undefined},...(settings.value?.policy.collaborators??[])]);
const workers=computed(()=>people.value.filter(person=>person.role==='owner'||(person.capabilities?person.capabilities.includes('annotation.assign'):['annotator','editor','lead','admin'].includes(person.role))));
const reviewers=computed(()=>people.value.filter(person=>person.role==='owner'||(person.capabilities?person.capabilities.includes('annotation.review'):['reviewer','lead','admin'].includes(person.role))));
const activeTask=computed(()=>data.value?.tasks.find(task=>task.id===activeId.value));
const visible=computed(()=>(data.value?.tasks??[]).filter(task=>filter.value==='all'||filter.value==='mine'&&task.participants.some(person=>person.id===app.status?.identity?.id)||filter.value==='review'&&task.reviewer.id===app.status?.identity?.id&&task.status==='awaiting-review'));
const sampleIds=computed(()=>activeTask.value?.rowIds.slice((samplePage.value-1)*50,samplePage.value*50)??[]);
const labels:Record<string,string>={'setting-up':'创建分支中',assigned:'待标注','in-progress':'进行中','awaiting-review':'待复核','changes-requested':'已退回',approved:'复核通过',merged:'已合并',cancelled:'已撤销','setup-failed':'分支创建失败'};
let generation=0;
async function load(){const current=++generation,base=props.base;loading.value=true;error.value='';try{const [summary,policy]=await Promise.all([request<WorkflowSummary>(base+'/tasks'),request<RepositorySettingsState>(base+'/settings')]);if(current!==generation)return;data.value=summary;settings.value=policy;if(activeId.value&&!summary.tasks.some(task=>task.id===activeId.value))activeId.value='';}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)loading.value=false;}}
watch(()=>props.base,load,{immediate:true});watch(activeId,()=>{selected.value=[];samplePage.value=1;replacement.value=activeTask.value?.reviewer.id??'';reviewComment.value='';});onBeforeUnmount(()=>++generation);
function open(task:AnnotationTaskView,rowId?:string){const participant=task.participants.find(person=>person.id===app.status?.identity?.id)??task.participants[0];if(participant)emit('open',task.id,participant.branch,rowId??task.rowIds[0]);}
async function create(){if(busy.value||!form.value.assigneeIds.length)return;busy.value=true;error.value='';try{const branches=await request<BranchItem[]>(props.base+'/branches'),source=branches.find(branch=>branch.name===props.branch);if(!source)throw new Error('当前分支不存在，请刷新项目。');const created=await post<AnnotationTaskView[]>(props.base+'/tasks',{...form.value,ref:props.branch,expectedCommit:source.commitId});showCreate.value=false;await load();activeId.value=created[0]?.id??'';emit('changed');app.notify(`已创建 ${created.length} 个任务，按稳定样本 ID 分配`);}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
async function cancel(){const task=activeTask.value;if(!task||busy.value)return;if(!reviewComment.value.trim()){error.value='请先在备注中填写撤销原因。';return;}if(!await app.confirmAction('撤销后执行者将失去该任务分支的任务授权，已有提交仍保留。',{title:'撤销任务',confirmLabel:'撤销任务'}))return;busy.value=true;error.value='';try{await post(props.base+`/tasks/${task.id}/cancel`,{expectedRevision:task.revision,reason:reviewComment.value.trim()});await load();app.notify('任务已撤销，历史提交保留');}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
async function changeReviewer(){const task=activeTask.value;if(!task||busy.value)return;busy.value=true;error.value='';try{await patch(props.base+`/tasks/${task.id}/reviewer`,{expectedRevision:task.revision,reviewerId:replacement.value});await load();app.notify('复核人员已更新，旧审批不再用于当前任务');}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
async function review(verdict:'approved'|'changes-requested'){const task=activeTask.value;if(!task||!selected.value.length||busy.value)return;if(verdict==='changes-requested'&&!reviewComment.value.trim()){error.value='请填写退回原因。';return;}if(!await app.confirmAction(`确认对已核对的 ${selected.value.length} 条样本执行${verdict==='approved'?'复核通过':'退回'}？`,{title:'批量复核',confirmLabel:verdict==='approved'?'通过所选样本':'退回所选样本'}))return;busy.value=true;error.value='';try{await post(props.base+`/tasks/${task.id}/review`,{expectedRevision:task.revision,decisions:selected.value.map(rowId=>({rowId,verdict,comment:reviewComment.value}))});await load();selected.value=[];emit('changed');app.notify('复核结果已写入 Oxen 版本记录');}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
function togglePage(checked:boolean){selected.value=checked?[...new Set([...selected.value,...sampleIds.value])]:selected.value.filter(id=>!sampleIds.value.includes(id));}
</script>
<template>
<section class="tasks-page">
  <header class="panel-header"><div><h2><ClipboardList :size="20"/>任务与复核</h2><p>以稳定样本 ID 分工，在个人分支完成标注，再由另一人复核与合并。</p></div><div class="task-actions"><button class="btn" :disabled="loading||busy" @click="load"><RefreshCw :size="15"/>刷新</button><button v-if="canManage" class="btn btn-primary" @click="showCreate=true"><Plus :size="16"/>分配任务</button></div></header>
  <div v-if="data" class="task-stats"><div><span>可查看的任务</span><strong>{{data.total}}</strong></div><div><span>待复核</span><strong>{{data.awaitingReview}}</strong></div><div><span>复核通过</span><strong>{{data.approved}}</strong></div><div><span>内容已变化</span><strong>{{data.stale}}</strong></div></div>
  <div v-if="error" class="error-state" role="alert">{{error}}<button class="btn" @click="load">重新加载</button></div>
  <div class="task-filter"><button v-for="item in [{id:'all',name:'全部'},{id:'mine',name:'我的标注'},{id:'review',name:'待我复核'}]" :key="item.id" :class="{active:filter===item.id}" @click="filter=item.id">{{item.name}}</button></div>
  <div v-if="loading&&!data" class="empty" role="status"><LoaderCircle class="spin" :size="24"/>正在读取任务…</div>
  <div v-else-if="!visible.length" class="empty panel"><ClipboardList :size="30"/><h3>当前没有匹配的任务</h3><p>{{canManage?'选择执行者与复核者，系统会按样本 ID 均分并创建独立分支。':'负责人分配任务后，你可以在这里继续标注或复核。'}}</p></div>
  <div v-else class="task-list"><article v-for="task in visible" :key="task.id" class="task-card" :class="{selected:task.id===activeId}"><header><button class="task-title" @click="activeId=task.id">{{task.title}}</button><span class="task-status" :class="task.status">{{labels[task.status]}}</span></header><p><Users :size="14"/>{{task.participants.map(person=>person.name).join('、')}}<span>复核：{{task.reviewer.name}}</span></p><div class="task-progress"><span :style="{width:(task.progress.total?task.progress.approved/task.progress.total*100:0)+'%'}"></span></div><footer><span>{{task.progress.total.toLocaleString()}} 条 · 已标 {{task.progress.annotated}} · 通过 {{task.progress.approved}}</span><button class="btn btn-ghost" @click="open(task)">打开工作台<ArrowRight :size="14"/></button><button class="btn btn-ghost" @click="activeId=activeId===task.id?'':task.id">详情</button></footer><p v-if="task.staleReason" class="notice">{{task.staleReason}}</p><p v-if="task.setupError" class="error-state">{{task.setupError}}</p></article></div>
  <section v-if="activeTask" class="panel task-detail"><header class="panel-header"><div><h3>{{activeTask.title}}</h3><p>{{activeTask.mode==='independent'?'两人独立标注后仲裁':'一人标注，另一人复核'}} · 基线 {{activeTask.baselineCommitId.slice(0,10)}} · r{{activeTask.revision}}</p></div><button class="icon-button" aria-label="关闭任务详情" @click="activeId=''"><X :size="18"/></button></header><div class="task-branches"><span v-for="person in activeTask.participants" :key="person.id"><GitBranch :size="13"/>{{person.name}} · <code>{{person.branch}}</code></span></div><p v-if="activeTask.note" class="notice">{{activeTask.note}}</p><div v-if="activeTask.permissions.review" class="task-review-toolbar"><label><input type="checkbox" :checked="selected.length===activeTask.rowIds.length" @change="selected=($event.target as HTMLInputElement).checked?[...activeTask.rowIds]:[]"/>选择全部 {{activeTask.rowIds.length}} 条</label><span>已选 {{selected.length}} 条</span><button class="btn btn-primary" :disabled="busy||!selected.length||!activeTask.current" @click="review('approved')"><CheckCheck :size="15"/>通过所选</button><button class="btn" :disabled="busy||!selected.length" @click="review('changes-requested')">退回所选</button></div><div class="task-records"><table><thead><tr><th v-if="activeTask.permissions.review"><input type="checkbox" aria-label="选择本页样本" :checked="sampleIds.length>0&&sampleIds.every(id=>selected.includes(id))" @change="togglePage(($event.target as HTMLInputElement).checked)"/></th><th>稳定样本 ID</th><th>操作</th></tr></thead><tbody><tr v-for="rowId in sampleIds" :key="rowId"><td v-if="activeTask.permissions.review"><input v-model="selected" type="checkbox" :value="rowId" :aria-label="'选择 '+rowId"/></td><td class="mono">{{rowId}}</td><td><button class="btn btn-ghost" @click="open(activeTask,rowId)">查看内容与证据<ArrowRight :size="13"/></button></td></tr></tbody></table></div><div class="task-pagination"><span>共 {{activeTask.rowIds.length}} 条</span><button class="btn" :disabled="samplePage<=1" @click="samplePage--">上一页</button><span>{{samplePage}} / {{Math.max(1,Math.ceil(activeTask.rowIds.length/50))}}</span><button class="btn" :disabled="samplePage*50>=activeTask.rowIds.length" @click="samplePage++">下一页</button></div><label v-if="activeTask.permissions.review||activeTask.permissions.manage" class="field">复核备注 / 管理原因<textarea v-model="reviewComment" rows="2" maxlength="4000" placeholder="退回、撤销时请填写明确原因"/></label><div v-if="activeTask.permissions.manage" class="task-admin"><label>复核人员<select v-model="replacement"><option v-for="person in reviewers" :key="person.id" :value="person.id" :disabled="activeTask.participants.some(member=>member.id===person.id)">{{person.name}}</option></select></label><button class="btn" :disabled="busy||replacement===activeTask.reviewer.id" @click="changeReviewer">调整复核人</button><button class="btn btn-danger" :disabled="busy||activeTask.status==='cancelled'" @click="cancel">撤销任务</button></div></section>
  <div v-if="showCreate" class="modal-backdrop" @click.self="!busy&&(showCreate=false)"><section class="modal task-create" role="dialog" aria-modal="true" aria-labelledby="task-create-title" @keydown.esc="!busy&&(showCreate=false)"><header class="panel-header"><div><h2 id="task-create-title">分配标注任务</h2><p>从 {{branch}} 的同一提交创建分支；普通模式按人数均分，独立双标为两人分配同一批样本。</p></div><button class="icon-button" :disabled="busy" aria-label="关闭" @click="showCreate=false"><X :size="18"/></button></header><form @submit.prevent="create"><fieldset :disabled="busy"><label class="field">任务标题<input v-model="form.title" required maxlength="180" placeholder="AI 安全样本复核"/></label><label class="field">模式<select v-model="form.mode"><option value="review">一人标注 + 另一人复核（多人均分）</option><option value="independent">两人独立标注 + 分歧仲裁</option></select></label><div class="field"><span>执行人员</span><div class="task-members"><label v-for="person in workers" :key="person.id"><input v-model="form.assigneeIds" type="checkbox" :value="person.id"/>{{person.name}}</label></div><small>已选 {{form.assigneeIds.length}} 人{{form.mode==='independent'?'，请恰好选择两人':''}}；按稳定样本 ID 分配，不按页码分配。</small></div><label class="field">复核人员<select v-model="form.reviewerId" required><option v-for="person in reviewers" :key="person.id" :value="person.id" :disabled="form.assigneeIds.includes(person.id)">{{person.name}}</option></select></label><label class="field">分支名前缀<input v-model="form.branchPrefix" required maxlength="90" pattern="[A-Za-z0-9_./-]+"/></label><label class="field">任务说明<textarea v-model="form.note" rows="3" maxlength="4000" placeholder="本次标注重点与判定注意事项"/></label></fieldset><p v-if="error" class="error-state">{{error}}</p><footer class="modal-actions"><button type="button" class="btn" :disabled="busy" @click="showCreate=false">取消</button><button class="btn btn-primary" :disabled="busy||!form.assigneeIds.length||form.assigneeIds.includes(form.reviewerId)||(form.mode==='independent'&&form.assigneeIds.length!==2)"><LoaderCircle v-if="busy" class="spin" :size="16"/>{{busy?'正在创建任务分支…':'创建并分配'}}</button></footer></form></section></div>
</section>
</template>
<style scoped>
.tasks-page h2{display:flex;align-items:center;gap:9px}.task-actions{display:flex;gap:8px}.task-stats{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--line);border-radius:7px;margin:20px 0;background:var(--surface)}.task-stats>div{padding:17px 22px;border-right:1px solid var(--line)}.task-stats>div:last-child{border:0}.task-stats span{display:block;color:var(--muted);font-size:11px}.task-stats strong{display:block;font-size:25px;font-weight:550;margin-top:7px}.task-filter{display:flex;gap:4px;border-bottom:1px solid var(--line);margin-bottom:18px}.task-filter button{padding:10px 16px;font-size:12px;color:var(--muted);border-bottom:2px solid transparent}.task-filter button.active{color:var(--text);border-color:var(--primary)}.task-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.task-card{border:1px solid var(--line);border-radius:7px;background:var(--surface);padding:18px;min-width:0}.task-card.selected{border-color:var(--primary)}.task-card header{display:flex;gap:12px;align-items:center;justify-content:space-between}.task-title{text-align:left;font-size:14px;font-weight:550;overflow-wrap:anywhere}.task-status{font-size:10px;border:1px solid var(--line);border-radius:12px;padding:2px 9px;color:var(--muted);white-space:nowrap}.task-status.approved,.task-status.merged{color:#8fcca6;border-color:#385c45}.task-status.changes-requested,.task-status.setup-failed{color:#e5b58e;border-color:#70513a}.task-card>p{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-top:12px;font-size:11px;color:var(--muted)}.task-card>p>span{margin-left:auto}.task-progress{height:4px;background:var(--line);border-radius:3px;margin:17px 0 12px;overflow:hidden}.task-progress>span{display:block;height:100%;background:#88b99a}.task-card footer{display:flex;align-items:center;gap:4px;flex-wrap:wrap}.task-card footer>span{font-size:11px;color:var(--muted);margin-right:auto}.task-card footer .btn{font-size:11px;padding:3px 5px;min-height:26px}.task-detail{margin-top:24px;padding:22px}.task-branches{display:flex;gap:12px;flex-wrap:wrap;margin:13px 0}.task-branches>span{display:flex;gap:6px;align-items:center;font-size:11px;color:var(--muted)}.task-branches code{overflow-wrap:anywhere;color:var(--text)}.task-records{overflow:auto;border:1px solid var(--line);border-radius:6px;margin:13px 0}.task-records table{width:100%;font-size:12px;border-collapse:collapse}.task-records th,.task-records td{padding:9px 12px;border-bottom:1px solid var(--line);text-align:left}.task-records th{background:var(--surface-raised);font-size:11px;color:var(--muted);font-weight:500}.task-records td .btn{font-size:11px;min-height:25px;padding:3px 6px}.task-review-toolbar,.task-pagination,.task-admin{display:flex;align-items:center;gap:10px;flex-wrap:wrap;font-size:12px}.task-review-toolbar{padding:11px 0}.task-review-toolbar label{display:flex;align-items:center;gap:7px}.task-review-toolbar>span{color:var(--muted);margin-right:auto}.task-pagination{justify-content:flex-end;margin:14px 0 20px}.task-pagination>span:first-child{margin-right:auto;color:var(--muted)}.task-pagination .btn{font-size:11px;min-height:28px}.task-admin{border-top:1px solid var(--line);padding-top:16px;margin-top:20px}.task-admin label{display:flex;gap:9px;align-items:center}.task-admin select{font-size:12px;background:var(--surface);border:1px solid var(--line);border-radius:5px;padding:7px}.task-create{max-width:680px}.task-members{display:flex;gap:10px;flex-wrap:wrap;padding:8px 0}.task-members label{display:flex;align-items:center;gap:7px;border:1px solid var(--line);border-radius:5px;padding:8px 11px;font-size:12px}.task-create fieldset{border:0;padding:0}.task-create .field small{color:var(--muted);font-size:11px}@media(max-width:760px){.task-list{grid-template-columns:1fr}.task-stats>div{padding:13px}.task-detail{padding:15px}.task-status{white-space:normal}.task-actions .btn{font-size:11px}.tasks-page>.panel-header{flex-wrap:wrap}}
</style>
